109	/** For every plan on the sheet in the order added, adds a DRAFT claim of the plan's amount, dated the day with an empty
110	 *  note, for each plan date (see PlanDates; a date its pauses skip makes none) up to its end and the sheet's today that the plan has made
111	 *  none for yet, as AddClaim adds one: a date the claim form's rules refuse (see ClaimRules) is skipped, to be tried
112	 *  again next time. Writes CLAIM_ADDED for each (then LATE_ENTRY for a late entry), then the figures the generate moved
113	 *  (see Rollup). Publishes how many were made. */
114	public class GeneratePlans {
115	    public void generate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateRequest request,
116	            @Val RollupBefore before, PlanRepository plans, PersonRepository people, ClaimRepository claims,
117	            SettingRepository settings, PeriodRepository periods, HolidayRepository holidays, SheetRepository sheets,
118	            ClaimLog log, Rollup rollup, Audit audit, Out<GenerateResult> result) {
119	        String sheet = sheetId.trim();
120	        String by = request == null || request.by() == null ? "" : request.by().trim();
121	        LocalDate today = sheets.today(sheet);
122	        int made = 0;
123	        for (Plan plan : plans.list(sheet, null)) {
124	            Person person = people.find(sheet, plan.personId());
125	            if (person == null) {
126	                continue;
127	            }
128	            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
129	            for (LocalDate date : PlanDates.upTo(plan, last)) {
130	                if (plans.made(plan.id(), date)) {
131	                    continue;
132	                }
133	                ClaimValues values = new ClaimValues(plan.amount(), date, "", null, by, null, null);
134	                ClaimRules.Checked checked;
135	                try {
136	                    checked = ClaimRules.check(person, values, settings, periods, claims, holidays);
137	                } catch (InvalidClaimException e) {
138	                    continue;
139	                }
140	                Claim added = claims.add(sheet, person.id(), values.amount(), checked.date(), values.note(),
141	                        checked.corrects(), null, null, checked.dueBy(), checked.terms());
142	                log.write(added, by);
143	                plans.recordMade(sheet, plan.id(), date, added.id());
144	                audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + by + " person=" + person.name()
145	                        + " amount=" + added.amount().toPlainString() + " date=" + added.date());
146	                if (periods.softClosedOn(sheet, checked.dueBy())) {
147	                    claims.markLateEntry(added);
148	                    audit.record("LATE_ENTRY sheet=" + sheet + " by=" + by + " person=" + person.name()
149	                            + " amount=" + added.amount().toPlainString() + " date=" + added.date());
150	                }
151	                made++;
152	            }
153	        }
154	        rollup.record(sheet, by, before);
155	        result.set(new GenerateResult(made));
156	    }
157	}
