246	/** A plan's dates up to a last date: the start, then every N days; or, monthly, the plan's day in every month from the
247	 *  start's month (a day beyond the month's length falling on its last day), dates before the start left out. A date
248	 *  one of the plan's pauses covers is skipped, not postponed (see PlanPause). */
249	public final class PlanDates {
250	    private PlanDates() {
251	    }
