253	    public static List<LocalDate> upTo(Plan plan, LocalDate last) {
254	        List<LocalDate> dates = new ArrayList<>();
255	        if (plan.day() != null) {
256	            for (LocalDate month = plan.start().withDayOfMonth(1); !month.isAfter(last); month = month.plusMonths(1)) {
257	                LocalDate date = month.withDayOfMonth(Math.min(plan.day(), month.lengthOfMonth()));
258	                if (!date.isBefore(plan.start()) && !date.isAfter(last) && !plan.skips(date)) {
259	                    dates.add(date);
260	                }
261	            }
262	        } else {
263	            for (LocalDate date = plan.start(); !date.isAfter(last); date = date.plusDays(plan.every())) {
264	                if (!plan.skips(date)) {
265	                    dates.add(date);
266	                }
267	            }
268	        }
269	        return dates;
270	    }
271	
272	    /** The plan's first {@code count} dates after the day and on or before its end. */
273	    public static List<LocalDate> after(Plan plan, LocalDate day, int count) {
274	        List<LocalDate> next = new ArrayList<>();
275	        for (LocalDate date : upTo(plan, plan.end())) {
276	            if (next.size() == count) {
277	                break;
278	            }
279	            if (date.isAfter(day)) {
280	                next.add(date);
281	            }
282	        }
283	        return next;
284	    }
