357	    public List<Plan> list(String sheetId, LocalDate asOf) {
358	        Date until = asOf == null ? null : Date.valueOf(asOf);
359	        Map<Long, List<PlanPause>> pauses = pauses(sheetId, asOf);
360	        return jdbc.query("SELECT p.id, p.person_id, p.amount, p.start_date, p.every_days, p.month_day, p.end_date,"
