577	package net.officefloor.hq.app.plan;
578	
579	import java.time.LocalDate;
580	import java.time.format.DateTimeParseException;
581	import net.officefloor.hq.app.claim.ClaimRequest;
582	import net.officefloor.hq.app.claim.ClaimValues;
583	import net.officefloor.hq.app.claim.InvalidClaimException;
584	import net.officefloor.plugin.variable.Out;
585	import org.springframework.web.bind.annotation.RequestBody;
586	
587	/** Reads the body: the amount is one the claim form takes for a claim that corrects nothing (a number 0.00 or more
588	 *  with up to two decimals, see ClaimValues); the start and end are yyyy-MM-dd, the end not before the start; every N
589	 *  days is a whole number, at least 1 — or, instead, a day of the month is a whole number from 1 to 31 (not both). */
590	public class ValidatePlan {
591	    public void validate(@RequestBody PlanRequest request, Out<PlanValues> values) throws InvalidPlanException {
592	        if (request == null) {
593	            throw new InvalidPlanException("A plan is required");
594	        }
595	        ClaimValues claim;
596	        try {
597	            claim = ClaimValues.from(new ClaimRequest(request.amount(), null, "", null, request.by(), null, null));
598	        } catch (InvalidClaimException e) {
599	            throw new InvalidPlanException(e.getMessage());
600	        }
601	        if (claim.amount().signum() < 0) {
602	            throw new InvalidPlanException("A plan's amount must be 0.00 or more");
603	        }
604	        LocalDate start = date(request.start(), "start");
605	        LocalDate end = date(request.end(), "end");
606	        if (end.isBefore(start)) {
607	            throw new InvalidPlanException("A plan's end must not be before its start");
608	        }
609	        String every = request.every() == null ? "" : request.every().trim();
610	        String day = request.day() == null ? "" : request.day().trim();
611	        if (!day.isEmpty()) {
612	            if (!every.isEmpty()) {
613	                throw new InvalidPlanException("A plan runs every N days or on a day of the month, not both");
614	            }
615	            if (!day.matches("\\d{1,2}") || Integer.parseInt(day) < 1 || Integer.parseInt(day) > 31) {
616	                throw new InvalidPlanException("A plan's day of the month must be a whole number from 1 to 31");
617	            }
618	            values.set(new PlanValues(claim.amount(), start, null, Integer.parseInt(day), end, claim.by()));
619	            return;
620	        }
621	        if (!every.matches("\\d{1,6}") || Integer.parseInt(every) < 1) {
622	            throw new InvalidPlanException("A plan's interval must be a whole number of days, at least 1");
623	        }
624	        values.set(new PlanValues(claim.amount(), start, Integer.parseInt(every), null, end, claim.by()));
625	    }
626	
627	    private static LocalDate date(String typed, String what) throws InvalidPlanException {
628	        try {
629	            return LocalDate.parse(typed == null ? "" : typed.trim());
630	        } catch (DateTimeParseException e) {
631	            throw new InvalidPlanException("A plan's " + what + " must be yyyy-MM-dd");
632	        }
633	    }
634	}
635	-- A person's plans: an amount, a start date, every N days (1 or more) and an end date, kept in the order added. A
636	-- generate makes a DRAFT claim for each plan date that has none yet; plan_claim records the dates a plan has made a
637	-- claim for, so a date is made once and how many a plan has made is known. added_on (a plan) and
638	-- made_on (a claim it made) are the sheet's today then, so the plans can be read as of a date.
639	CREATE TABLE plan (
640	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
641	    sheet_id   VARCHAR(200)   NOT NULL,
642	    person_id  BIGINT         NOT NULL,
643	    amount     DECIMAL(17, 2) NOT NULL,
644	    start_date DATE           NOT NULL,
645	    every_days INT            NOT NULL,
646	    end_date   DATE           NOT NULL,
647	    added_on   DATE
648	);
649	CREATE INDEX plan_sheet ON plan (sheet_id, id);
650	
651	CREATE TABLE plan_claim (
652	    plan_id   BIGINT NOT NULL REFERENCES plan (id),
653	    plan_date DATE   NOT NULL,
654	    claim_id  BIGINT NOT NULL,
655	    made_on   DATE,
656	    PRIMARY KEY (plan_id, plan_date)
657	);
658	-- A plan's pauses, in the order made: paused_on is the sheet's today when it was paused, resumed_on the sheet's today
659	-- when it was resumed (null while it stays paused). A plan date on or after paused_on and before resumed_on is skipped.
660	-- A plan has at most one pause with a null resumed_on: it is then paused.
661	CREATE TABLE plan_pause (
662	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
663	    plan_id    BIGINT NOT NULL REFERENCES plan (id),
664	    paused_on  DATE   NOT NULL,
665	    resumed_on DATE
666	);
667	CREATE INDEX plan_pause_plan ON plan_pause (plan_id, id);
